class ATM:
    def __init__(self):
        self.counts = [0] * 5
        self.notes = [20, 50, 100, 200, 500]

    def deposit(self, banknotesCount: List[int]) -> None:
        for i in range(5):
            self.counts[i] += banknotesCount[i]

    def withdraw(self, amount: int) -> List[int]:
        res = [0] * 5
        for i in range(4, -1, -1):
            take = min(self.counts[i], amount // self.notes[i])
            res[i] = take
            amount -= take * self.notes[i]
        if amount > 0:
            return [-1]
        for i in range(5):
            self.counts[i] -= res[i]
        return res

