            long long take = min<long long>(counts[i], amount / notes[i]);
            res[i] = take;
            amount -= take * notes[i];
        }
        if (amount > 0) return {-1};
        for (int i = 0; i < 5; i++) counts[i] -= res[i];
        return res;
    }
private:
