class ATM {
    private static final int[] NOTES = {20, 50, 100, 200, 500};
    private final long[] counts = new long[5];

    public ATM() {
    }

    public void deposit(int[] banknotesCount) {
        for (int i = 0; i < 5; i++) {
            counts[i] += banknotesCount[i];
        }
    }

    public int[] withdraw(int amount) {
        int[] res = new int[5];
        long remaining = amount;
        for (int i = 4; i >= 0; i--) {
            long take = Math.min(counts[i], remaining / NOTES[i]);
            res[i] = (int) take;
            remaining -= take * NOTES[i];
        }
        if (remaining > 0) {
            return new int[]{-1};
        }
        for (int i = 0; i < 5; i++) {
            counts[i] -= res[i];
        }
        return res;
    }
}

