var ATM = function() {
    this.counts = new Array(5).fill(0);
    this.notes = [20, 50, 100, 200, 500];
};

ATM.prototype.deposit = function(banknotesCount) {
    for (let i = 0; i < 5; i++) {
        this.counts[i] += banknotesCount[i];
    }
};

ATM.prototype.withdraw = function(amount) {
    const res = new Array(5).fill(0);
    for (let i = 4; i >= 0; i--) {
        res[i] = Math.min(this.counts[i], Math.floor(amount / this.notes[i]));
        amount -= res[i] * this.notes[i];
    }
    if (amount > 0) {
        return [-1];
    }
    for (let i = 0; i < 5; i++) {
        this.counts[i] -= res[i];
    }
    return res;
};
